select

from profile_meta_datasource_schema
where 1 = 1

  and status = #{status,jdbcType=INTEGER}


  and schema_id = #{schemaId,jdbcType=INTEGER}


  and schema_name = #{schemaName,jdbcType=VARCHAR}


  and schema_type = #{schemaType,jdbcType=VARCHAR}


  and source_type = #{sourceType,jdbcType=INTEGER}


  and creator = #{creator,jdbcType=VARCHAR}


  and modifier = #{modifier,jdbcType=VARCHAR}
